var MyRecordOfType v_myVariable := {
     [0] := '111'B,
     [1] := '101'B,
     [2] :=   }
  v_myVariable := { '10111'B, -, - };
  // after this, v_myVariable contains:
  // { '10111'B, '101'B /* unchanged */, <undefined> /* unchanged */ }
  v_myVariable :=
  {
     [1] := '010'B,
  }
